param([string]$Configuration="Release",[string]$Platform="x64",[switch]$SkipBuild)
$ErrorActionPreference="Stop"; $root=Resolve-Path (Join-Path $PSScriptRoot ".."); $out=Join-Path $root "publish\ff_gui_app"; $build=Join-Path $root "$Platform\$Configuration"; $msbuild="D:\Program Files (x86)\Microsoft Visual Studio\2019\Community\MSBuild\Current\Bin\MSBuild.exe"
if(!$SkipBuild){& $msbuild (Join-Path $root "FF.sln") /p:Configuration=$Configuration /p:Platform=$Platform /p:ImportUserProps=false /m;if($LASTEXITCODE){throw "MSBuild failed"}}
if(Test-Path $out){Remove-Item $out -Recurse -Force};New-Item $out -ItemType Directory|Out-Null
Copy-Item "$build\ff_gui.exe" $out;Copy-Item "$root\third_party\MightyZap\bin\CppDllMightyZap_Ver2010.dll" $out;Copy-Item "$root\config\defaults\ff_config.json" "$out\ff_config.default.json";Copy-Item "$root\docs\FF_GUI_Usage.md" "$out\FF_GUI_Usage.md";$referenceDoc=Get-ChildItem (Join-Path $root "docs\architecture") -Filter "*.md"|Select-Object -First 1;if($referenceDoc){Copy-Item $referenceDoc.FullName "$out\FF_SDK_Reference.md"};New-Item "$out\config" -ItemType Directory|Out-Null;Copy-Item "$root\config\templates\*" "$out\config" -Recurse
$redist=Get-ChildItem 'D:\Program Files (x86)\Microsoft Visual Studio\2019\Community\VC\Redist\MSVC' -Recurse -Filter 'vc_redist.x64.exe' -ErrorAction SilentlyContinue | Select-Object -First 1;if($redist){Copy-Item $redist.FullName "$out\vc_redist.x64.exe"}
Write-Host "Published: $out"
